theorem ValidMemRange.get {addr : Word} {n : Nat}
    (h : ValidMemRange addr n) {i : Nat} (hi : i < n) :
    isValidDwordAccess (addr + BitVec.ofNat 64 (8 * i)) = true

theorem ProgramAt.get {code : CodeMem} {base : Word} {prog : List Instr}
    (h : ProgramAt code base prog) {i : Nat} (hi : i < prog.length) :
    code (base + BitVec.ofNat 64 (4 * i)) = prog[i]?

theorem ProgramAt.prefix {code : CodeMem} {base : Word} {prog1 prog2 : List Instr}
    (h : ProgramAt code base (prog1 ++ prog2)) :
    ProgramAt code base prog1

theorem ProgramAt.suffix {code : CodeMem} {base : Word} {prog1 prog2 : List Instr}
    (h : ProgramAt code base (prog1 ++ prog2)) :
    ProgramAt code (base + BitVec.ofNat 64 (4 * prog1.length)) prog2

theorem loadProgram_programAt {base : Word} {prog : List Instr}
    (hlen : 4 * prog.length < 2^64) :
    ProgramAt (loadProgram base prog) base prog

theorem step_ebreak {s : MachineState}
    (hfetch : s.code s.pc = some .EBREAK) :
    step s = none

theorem step_ecall_halt {s : MachineState}
    (hfetch : s.code s.pc = some .ECALL) (ht0 : s.getReg .x5 = 0) :
    step s = none

@[simp] theorem Program.getElem?_append (p q : Program) (i : Nat) :
    @getElem? (List Instr) Nat Instr _ _ (p ++ q) i =
    if i < p.length then @getElem? (List Instr) Nat Instr _ _ p i
    else @getElem? (List Instr) Nat Instr _ _ q (i - p.length)

theorem platformFrame_withMem (s : SailState) (m : Std.ExtHashMap Nat (BitVec 8))
    (hmono : ∀ n : Nat, (s.mem.get? n).isSome → (m.get? n).isSome) :
    PlatformFrame s { s with mem := m }

theorem stateRel_PC_insert {sRv : MachineState} {sSail : SailState}
    (hrel : StateRel sRv sSail) (v : BitVec 64) :
    StateRel sRv { sSail with regs := sSail.regs.insert Register.PC v }

theorem MemPresent.insert {lo hi : Nat} {mem : Std.ExtHashMap Nat (BitVec 8)}
    (h : MemPresent lo hi mem) (k : Nat) (v : BitVec 8) :
    MemPresent lo hi (mem.insert k v)

theorem step_eq_execInstrBr {s s' : MachineState} {i : Instr}
    (hfetch : s.code s.pc = some i) (hsim : i.simulable = true)
    (hstep : step s = some s') : s' = execInstrBr s i

theorem runSail_sailStep_eq {si : SailInstr} {sSail : SailState} {pc : BitVec 64}
    (h_pc : sSail.regs.get? Register.PC = some pc) :
    runSail (sailStep si) sSail
      = runSail (executeSupported si >>= fun _ => tick_pc ())
          { sSail with regs := sSail.regs.insert Register.nextPC (pc + 4) }

theorem jalr_sideCond_of_runInv {lo hi : Nat} {sRv : MachineState} {sSail : SailState}
    {rd rs1 : Reg} {offset : BitVec 12}
    (hinv : RunInv lo hi sRv sSail)
    (h_nextpc : sSail.regs.get? Register.nextPC = some (sRv.pc + 4))
    (h_align : ((sRv.getReg rs1 + signExtend12 offset) &&& ~~~1#64) &&& 3 = 0) :
    instrSideCond (.JALR rd rs1 offset) sRv sSail

theorem sailStepN_succ_of {n : Nat} {sRv sRv' : MachineState} {si : SailInstr}
    (hsi : sRv.code sRv.pc >>= toSailInstr? = some si) (hstep : step sRv = some sRv') :
    sailStepN (n + 1) sRv = sailStep si >>= fun _ => sailStepN n sRv'

theorem stateRel_nextPC {sRv : MachineState} {sSail : SailState}
    (hrel : StateRel sRv sSail) (v : BitVec 64) :
    StateRel sRv { sSail with regs := sSail.regs.insert Register.nextPC v }

