    (writeBytes a v : SailM Bool) s
      = .ok true { s with mem := s.mem.insert a (v.extractLsb' 0 8) }

private theorem to_bits_truncate_neg_pow63 :
    to_bits_truncate (l := 64) (-(((2 : Int) ^ 63))) =
    to_bits_truncate (l := 64) (((2 : Int) ^ 63))

theorem BytesPresent.elim1 {mem : Std.ExtHashMap Nat (BitVec 8)} {a : Nat}
    (h : BytesPresent mem a 1) :
    ∃ b0 : BitVec 8, mem.get? a = some b0

