theorem untilFuelM_one {m : Type → Type} [Monad m] [LawfulMonad m] {α}
    (cond : α → m Bool) (init : α) (f : α → m α) :
    untilFuelM 1 cond init f = (f init >>= fun x => cond x >>= fun _ => pure x)

theorem untilFuelM_one_pure {m : Type → Type} [Monad m] [LawfulMonad m] {α}
    (g : α → Bool) (init : α) (f : α → m α) :
    untilFuelM 1 (fun x => pure (g x)) init f = f init

theorem extentsOkFrom_mem {lo hi : Nat} {es : List (Nat × Program)}
    (h : extentsOkFrom lo hi es = true) :
    ∀ e ∈ es, lo ≤ e.1 ∧ e.1 + 4 * e.2.length ≤ hi

theorem ofProg_sub_ofEntries_of_extentsOk {lo hi : Nat}
    {es : List (Nat × Program)}
    (hok : extentsOkFrom lo hi es = true) (hhi : hi < 2 ^ 64) :
    ∀ e ∈ es, ∀ a i,
      (CodeReq.ofProg (BitVec.ofNat 64 e.1) e.2) a = some i →
      ofEntries es a = some i

theorem cpsTripleWithin_weaken {nSteps : Nat} {entry exit_ : Word} {cr : CodeReq}
    {P P' Q Q' : Assertion}
    (hpre  : ∀ h, P' h → P h)
    (hpost : ∀ h, Q h → Q' h)
    (h : cpsTripleWithin nSteps entry exit_ cr P Q) :
    cpsTripleWithin nSteps entry exit_ cr P' Q'

theorem cpsBranchWithin_weaken {nSteps : Nat} {entry : Word} {cr : CodeReq}
    {P P' : Assertion} {exit_t : Word} {Q_t Q_t' : Assertion}
    {exit_f : Word} {Q_f Q_f' : Assertion}
